/* =================================================
We are looking straight down upon four pendulums 
swinging from four pivot points on an oval track.
Elastic strings attach the four pendulum bobs to a central drawing pen.

       Pos  Len  Arc Speed
Red    <A>  <B>  <C>  <D>
Green  <E>  <F>  <G>  <H>
Blue   <I>  <J>  <K>  <L>
Yellow <M>  <N>  <O>  <P>

Pos   = position of Pendulum base on oval tack
Len   = distance of Pendulum pivot point from oval track (outside the track is allowed)
Arc   = how much the pendulum swings
Speed = how fast it swings 

Press code letter to increase parameter value, or <Shift> + letter to decrease value

Press <Space> to clear drawing
Press <Enter> to randomize parameter values

Press <X>     to toggle caligraphy pen ink style
Press <Q>,<W> to affect width of pen ink
Press <Y> to toggle pendulum drawing

Press <S> to toggle between straight swing vs. circular swing
Press <Z> to toggle auto movement of pendulums

Buffer A = data editing and storage
Buffer B = pendulum drawing 
Buffer C = pen drawing

1/6/25: switched to 3 pens all drawing
==================================================== */

void mainImage(out vec4 O, in vec2 U) {
    ivec2 I = ivec2(U);
    vec4 pendulumDrawing = texelFetch(iChannel1,I,0);    
    if(pendulumDrawing.w > 0.) {
        O = pendulumDrawing;
        return;
    }

    O = vec4(0.2);

    loadData(iChannel0);

    vec2 R = iResolution.xy;
    uv = (2.0 * U - R) / R.y;

    if(visible == 1.) {
        if(swing == 1.) { // circular swing
            for(int i=0;i<PCOUNT;++i) {
                float a = angle(i);
                vec2 center = vec2(cos(a)*ringRadius,sin(a)*ringRadius*aspect);
                a += PIh;
                float w = len(i);
                vec2 tp = center + rot(vec2(0.,w),a);

                if(abs(length(uv-tp) - arc(i)) < 0.003)
                    O.xyz = vec3(0.);
            }
        }

        // bobs, strings, pen drawing
        for(int i=0;i<PCOUNT;++i) line(pen,tip(i),0.003,vec3(.8),O,false);    
        for(int i=0;i<PCOUNT;++i) circle(tip(i),0.02,pColor[i],O);
        circle(pen,0.01,vec3(1),O);
    }

    vec4 c = texelFetch(iChannel2,I,0); // line drawing
    O = mix(O,c,c.w);
}

#define PCOUNT 4  
#define NONE 999. 

#define angle(i) q[i].x
#define len(i)   q[i].y
#define arc(i)   q[i].z
#define speed(i) q[i].w
#define tip(i)   q[PCOUNT+i].xy

#define pen       q[PCOUNT  ].zw
#define oldPen1   q[PCOUNT+1].zw
#define inkStyle  q[PCOUNT+2].z
#define swing     q[PCOUNT+2].w
#define visible   q[PCOUNT+3].z 
#define pAngle    q[PCOUNT+3].w

#define clearSand q[PCOUNT*2].x
#define drawPend  q[PCOUNT*2].y
#define autoMove  q[PCOUNT*2].z
#define caliWidth q[PCOUNT*2].w

#define oldPen2   q[PCOUNT*2+1].xy
#define oldPen3   q[PCOUNT*2+1].zw

const int QSIZE = PCOUNT * 2 + 2; // total storage
vec4 q[QSIZE];

void loadData(sampler2D channel) {
    for(int i=0;i<QSIZE;++i) 
        q[i] = texelFetch(channel,ivec2(i,0),0);
}

void saveData(inout vec4 O,vec2 U) {
    ivec2 I = ivec2(U);    
    if(I.y == 0 && I.x < QSIZE) 
        O = vec4(q[I.x]);
}

const float PI = acos(-1.);
const float PIh = PI * 0.5;
const float PI2 = PI * 2.;
const vec3 SILVER_COLOR = vec3(113./255.,121./255.,126./255.) * 1.5;
const float aspect = 0.55;
const float ringRadius = 1.75;
const vec3[] pColor = vec3[](vec3(1,0,0),vec3(0,1,0),vec3(0,0,1),vec3(1,1,0));
const float penOffset = 0.4;

vec2 uv;

// ----------------------------------------------------------
#define KEY_SHIFT 16

bool keyDown(int keyCode,sampler2D channel) {
   return bool(texelFetch(channel, ivec2(keyCode,0), 0).x != 0.);
}

bool keyClick(int keyCode,sampler2D channel) {
   return bool(texelFetch(channel, ivec2(keyCode,1), 0).x != 0.);
}
// ----------------------------------------------------------
vec2 rot(vec2 p,float angle) {
    float dist = length(p);
    float a = atan(p.y,p.x) + angle; 
    return vec2(cos(a)*dist,sin(a)*dist);
}
// ----------------------------------------------------------
// https://www.shadertoy.com/view/MtfGWM
float random(vec2 c) { return fract(sin(dot(vec2(1.317 - c.x,19.753 + c.y),c))*413.7972); } // 0...1
// ----------------------------------------------------------
vec2 rndSeed = vec2(0);

float rnd() { // 0...1
    float ans = fract(sin(dot(vec2(1.317,19.753),rndSeed))*413.7972);  // 0...1
    rndSeed = vec2(ans, sin(ans));
    return ans;
}
//-------------------------------------------
float ptLineDistance(vec2 pt,vec2 lineP1,vec2 lineP2) {
    vec2 ab = lineP2-lineP1;
    vec2 be = pt-lineP2;     
    if(dot(ab,be) > 0.) return length(be);

    vec2 ae = pt-lineP1;
    if(dot(ab,ae) < 0.) return length(ae); 
    return abs(ab.x * ae.y - ab.y * ae.x) / length(ab);
}

void line(vec2 p1,vec2 p2, float width, vec3 color,inout vec4 O,bool edge) {
    float d = ptLineDistance(uv,p1,p2);
    if(d < width) {
        float d2 = ptLineDistance(uv - vec2(-width * 0.5,width * 0.5),p1,p2);
        O.xyz = color - vec3(d2 / (width * 2.5));

        if(edge && abs(d-width) < 0.005) O.xyz = vec3(0);
        O.w = 1.; // mark pixel as opaque
    }
}

void circle(vec2 pt, float radius, vec3 color,inout vec4 O) {
    float d = length(uv - pt);
    if(d < radius) {
        float d2 = length(uv - vec2(-radius * 0.3,radius * 0.3) - pt);
        O.xyz = color - vec3(d2 / (radius * 3.5));
        O.w = 1.; // mark pixel as opaque
    }

    if(abs(d - radius) < 0.002) O = vec4(0,0,0,1);
}

// ----------------------------------------------------------

void calcTip(int i) {
    float a = angle(i);
    vec2 center = vec2(cos(a)*ringRadius,sin(a)*ringRadius*aspect); // base center coord.        
    a += PIh;

    if(swing == 0.) {  // straight swing
        float w = len(i) + sin(iTime * speed(i)) * arc(i);
        tip(i) = center + rot(vec2(0.,w),a);
    }
    else {
        float v = len(i);
        vec2 tp = center + rot(vec2(0.,v),a);
        float angle = iTime * speed(i);
        tip(i) = tp + vec2(cos(angle)*arc(i),sin(angle)*arc(i));
    }      
}
// ----------------------------------------------------------
void calcPen() {
    vec2 total = vec2(0);
    for(int i=0;i<PCOUNT;++i) total += tip(i);
    pen = total/float(PCOUNT);
}
// ----------------------------------------------------------
void reset() {
    rndSeed = vec2(float(iFrame) + iDate.w * 3., float(iDate.w));

    for(int i=0;i<PCOUNT;++i) {
        float v = float(i);
        angle(i) = rnd() * PI2;
        len(i) = 0.1 + rnd() * 1.4;
        arc(i) = 0.5 + v * 0.1;
        speed(i) = 0.5 + v * 1.5;        
        calcTip(i);
    }

    oldPen1.x = NONE;
    calcPen();

    clearSand = 2.;
    drawPend = 2.;
    autoMove = 0.;
    caliWidth = 0.2 + rnd() * 0.8;
    inkStyle = 0.;
    swing = 0.;   // 0,1 = straight swing, circle swing
    visible = 1.;
    pAngle = 0.;
}
// ----------------------------------------------------------
void alterParam(int index) {
    int qIndex = index/4;
    int qField = index%4;

    float delta = 0.02;
    if(keyDown(KEY_SHIFT,iChannel3)) delta = -delta;

    if(qField == 3) delta *= 4.;   // speed

    float v = q[qIndex][qField] + delta;

    if(qField == 1) v = clamp(v,-1.,1.4); // len
    if(qField == 2) v = clamp(v,0.,1.);   // arc
    if(qField == 3) {
        v = clamp(v,0.,5.);   // speed
        oldPen1.x = NONE;      // marked so line drawing isn't drawn this cycle
    }

    q[qIndex][qField] = v;
    drawPend = 2.; 
}
// ----------------------------------------------------------
void processAutoMove() {
    for(int i=0;i<PCOUNT;++i) {
        float s = 0.006 + float(i) * 0.003;
        if(i==1 || i==3) s = -s;
        angle(i) = mod(angle(i) + s, PI2);
    }

    drawPend = 2.; 
}
// ----------------------------------------------------------
void mainImage(out vec4 O, in vec2 U) {
    if(U.x > float(QSIZE) || U.y > 1.0) return; // only update q[] storage

    if(iFrame < 2 || keyClick(13,iChannel3)) { // <Enter> reset
        reset();
        saveData(O,U);
        return;
    }

    loadData(iChannel0);    
    if(clearSand > 0.) clearSand -= 1.;
    if(drawPend > 0.) drawPend -= 1.;
    if(keyClick(32,iChannel3)) clearSand = 2.; // <Spc> clear drawing
    if(keyClick(90,iChannel3)) autoMove = 1.0 - autoMove; // <Z> toggle auto move

    oldPen1 = pen + vec2(cos(pAngle)*penOffset,sin(pAngle)*penOffset);
    oldPen2 = pen + vec2(cos(pAngle+PI2*.333)*penOffset,sin(pAngle+PI2*.333)*penOffset);
    oldPen3 = pen + vec2(cos(pAngle+PI2*.666)*penOffset,sin(pAngle+PI2*.666)*penOffset);
    pAngle += 0.03;

    for(int k=0;k<16;++k) 
        if(keyDown(65+k,iChannel3)) alterParam(k);

    if(keyDown(81,iChannel3)) caliWidth = min(caliWidth + 0.01, 1.);   // <Q>
    if(keyDown(87,iChannel3)) caliWidth = max(caliWidth - 0.01, 0.2);  // <W>
    if(keyClick(88,iChannel3)) inkStyle = 1. - inkStyle;               // <X>
    if(keyClick(83,iChannel3)) swing = 1. - swing;                     // <S>
    if(keyClick(89,iChannel3)) {                                       // <Y>
        visible = 1. - visible;
        drawPend = 2.; 
    } 

    if(autoMove > 0.) processAutoMove();

    for(int i=0;i<PCOUNT;++i) calcTip(i);
    calcPen();    

    saveData(O,U);
}

void drawPendulum(int i,inout vec4 O) {
    float a = angle(i);
    vec2 center = vec2(cos(a)*ringRadius,sin(a)*ringRadius*aspect); // base center coord     

    a += PIh;
    float v = len(i);
    vec2 tip = center + rot(vec2(0.,v),a);
    line(center,tip,0.003,SILVER_COLOR,O,false);
    circle(tip,0.01,SILVER_COLOR,O);

    const float w = 0.06; // base width    
    line(center + rot(vec2(0.,w),a),center + rot(vec2(0.,-w),a),0.02,pColor[i],O,true);
}
// -------------------------------------------
void mainImage( out vec4 O, vec2 U) {
    O = vec4(0); // .w = 0  -> mark as transparent
    loadData(iChannel0);
    if(iFrame > 2 && drawPend == 0.) { O = texelFetch(iChannel1,ivec2(U),0); return; }

    vec2 R = iResolution.xy;
    uv = (2.0 * U - R) / R.y;

    // screen edge
    float d = ringRadius + 0.01;
    float a = atan(uv.y,uv.x * aspect);
    vec2 oval = vec2(cos(a)*d,sin(a)*d*aspect);
    if(length(uv) > length(oval)) {
        O = vec4(0.84);
        if(random(U) < .2) O = vec4(0.75);
    }
    // oval ring
    float dist = abs(length(uv) - length(oval));
    if(dist < 0.02) O = vec4(1. - dist * 30.);

    if(visible == 1.)
        for(int i=0;i<PCOUNT;++i)
            drawPendulum(i,O);
}

void caligraphyLine(vec2 p1,vec2 p2,vec3 color,inout vec4 O) {
    if(p1 == p2) return;

    float width;
    float power = pow(length(p1-p2),caliWidth);
    if(inkStyle == .0)
        width = 0.002 + .75 * power;
    else
        width = 0.3 - .55 * power;

    float d = ptLineDistance(uv,p1,p2);
    if(d < width) {
        float w2 = width * 0.135;
        float d2 = ptLineDistance(uv - vec2(-w2,w2),p1,p2);
        O.xyz = max(O.xyz * .75, color - vec3(d2 / width)) * 1.2;

        // pseudo specular
        p1 = (p1+p2) * 0.5;
        if(uv.x > p1.x && uv.y > p1.y) O.xyz *= (1. + 0.1 * d);
        O.w = 1.; // mark as just drawn
    }
}
// ---------------------------------------------------------
vec3 jetColorMap(float t) { // 0 ... 1
  return clamp(vec3(1.5) - abs(4.0 * vec3(t) + vec3(-3., -2., -1.)), vec3(0.), vec3(1.));
}

// ---------------------------------------------------------
// https://stackoverflow.com/questions/3018313/algorithm-to-convert-rgb-to-hsv-and-hsv-to-rgb-in-range-0-255-for-both
// Source - https://stackoverflow.com/a
// Posted by Ray Hulha
// Retrieved 2026-01-03, License - CC BY-SA 3.0

vec3 HSV2RGB( vec3 hsv ) {
    hsv.x = mod( 100.0 + hsv.x, 1.0 ); // Ensure [0,1[
    float   HueSlice = 6.0 * hsv.x; // In [0,6[
    float   HueSliceInteger = floor( HueSlice );
    float   HueSliceInterpolant = HueSlice - HueSliceInteger; // In [0,1[ for each hue slice
    vec3  TempRGB = vec3(   hsv.z * (1.0 - hsv.y), hsv.z * (1.0 - hsv.y * HueSliceInterpolant), hsv.z * (1.0 - hsv.y * (1.0 - HueSliceInterpolant)) );
    float   IsOddSlice = mod( HueSliceInteger, 2.0 ); // 0 if even (slices 0, 2, 4), 1 if odd (slices 1, 3, 5)
    float   ThreeSliceSelector = 0.5 * (HueSliceInteger - IsOddSlice); // (0, 1, 2) corresponding to slices (0, 2, 4) and (1, 3, 5)
    vec3  ScrollingRGBForEvenSlices = vec3( hsv.z, TempRGB.zx );           // (V, Temp Blue, Temp Red) for even slices (0, 2, 4)
    vec3  ScrollingRGBForOddSlices = vec3( TempRGB.y, hsv.z, TempRGB.x );  // (Temp Green, V, Temp Red) for odd slices (1, 3, 5)
    vec3  ScrollingRGB = mix( ScrollingRGBForEvenSlices, ScrollingRGBForOddSlices, IsOddSlice );
    float   IsNotFirstSlice = clamp( ThreeSliceSelector, 0.0,1.0 );                   // 1 if NOT the first slice (true for slices 1 and 2)
    float   IsNotSecondSlice = clamp( ThreeSliceSelector-1.0, 0.0,1. );              // 1 if NOT the first or second slice (true only for slice 2)
    return  mix( ScrollingRGB.xyz, mix( ScrollingRGB.zxy, ScrollingRGB.yzx, IsNotSecondSlice ), IsNotFirstSlice );    // Make the RGB rotate right depending on final slice index
}

// ---------------------------------------------------------
void mainImage(out vec4 O, in vec2 U) {
    if(iFrame < 2) {
        O = vec4(0);
        return;
    }

    O = texelFetch(iChannel2,ivec2(U),0) * 0.995; // keep pixel colors alive   
    loadData(iChannel0);
    if(clearSand > 0.) O = vec4(0);

    vec2 R = iResolution.xy;
    uv = (2.0 * U - R) / R.y;

//    vec3 color = vec3(0.5) + jetColorMap(fract(iTime * 0.02));
    float h = 0.5 + sin(iTime * 0.25) * 0.5;  // color 0...1
    float s = 0.5 + sin(iTime * 0.5) * 0.5;   // saturation 0...1
    float v = 1. + sin(iTime) * 0.25;       // brightness 0...1    
    vec3 color = HSV2RGB(vec3(h,s,v));

    if(oldPen1.x != NONE) { // pen speed change not being made this cycle
        float offset = 0.2;
        caligraphyLine(pen + vec2(cos(pAngle)*penOffset,sin(pAngle)*penOffset),oldPen1,color,O);
        caligraphyLine(pen + vec2(cos(pAngle+PI2*.333)*penOffset,sin(pAngle+PI2*.333)*penOffset),oldPen2,color,O);
        caligraphyLine(pen + vec2(cos(pAngle+PI2*.666)*penOffset,sin(pAngle+PI2*.666)*penOffset),oldPen3,color,O);
    }
}
